#!/usr/bin/env python3
import sys, os, re, json, html, time, random, string, base64, ssl, socket
from urllib.parse import urlsplit, urlunsplit, urljoin, unquote
import http.client

VERSION = "Dirble 1.4.2 (commit d520c82, build 2026-04-17)"
HELP = """Fast directory scanning and scraping tool

Usage: executable [OPTIONS] <uri|--uri-file <uri-file>|--uri <uri>>

Arguments:
  [uri]
          The URI of the host to scan, optionally supports basic auth with
          http://user:pass@host:port

Options:
  -u, --uri <uri>
          Additional hosts to scan [aliases: url]
  -U, --uri-file <uri-file>
          The filename of a file containing a list of URIs to scan - cookies and
          headers set will be applied to all URIs [aliases: url-file]
      --verb <http_verb>
          Specify which HTTP verb to use
           [default: get] [possible values: get, head, post]
  -w, --wordlist <wordlist>
          Sets which wordlist to use, defaults to dirble_wordlist.txt in the same
          folder as the executable
  -p, --prefixes <prefixes>...
          Provides comma separated prefixes to extend queries with
  -P, --prefix-file <prefix-file>
          The name of a file containing extensions to extend queries with, one
          per line
  -x, --extensions <extensions>...
          Provides comma separated extensions to extend queries with
  -X, --extension-file <extension-file>
          The name of a file containing extensions to extend queries with, one
          per line
      --ext-sub
          Indicates whether the string "%EXT%" in a wordlist file should be 
          substituted with the current extension
  -f, --force-extension
          Only scan with provided extensions
  -k, --ignore-cert
          Ignore the certificate validity for HTTPS
      --show-htaccess
          Enable display of items containing .ht when they return 403 responses
      --timeout <timeout>
          Maximum time to wait for a response before giving up, given in seconds
           [default: 5]
      --max-errors <max_errors>
          The number of consecutive errors a thread can have before it exits,
          set to 0 to disable [default: 5]
      --json-file <json_file>
          Sets a file to write JSON output to [aliases: oJ]
      --no-color
          Disable coloring of terminal output
  -o, --output-file <output_file>
          Sets the file to write the report to [aliases: oN]
      --xml-file <xml_file>
          Sets a file to write XML output to [aliases: oX]
      --hide-lengths <length_blacklist>...
          Specify length ranges to hide, e.g. --hide-lengths 348,500-700
      --output-all <output_all>
          Stores all output types respectively as .txt, .json and .xml [aliases: oA]
      --burp
          Sets the proxy to use the default burp proxy values
          (http://localhost:8080)
      --no-proxy
          Disables proxy use even if there is a system proxy
      --proxy <proxy>
          The proxy address to use, including type and port, can also include a
          username and password in the form 
          "http://username:password@proxy_url:proxy_port"
  -t, --max-threads <max-threads>
          Sets the maximum number of request threads that will be spawned [default: 10]
  -T, --wordlist-split <wordlist_split>
          The number of threads to run for each folder/extension combo [default: 3]
  -z, --throttle <milliseconds>
          Time each thread will wait between requests, given in milliseconds
      --username <username>
          Sets the username to authenticate with
      --password <password>
          Sets the password to authenticate with
  -l, --scan-listable
          Scan listable directories
      --max-recursion-depth <max_recursion_depth>
          Sets the maximum directory depth to recurse to, 0 will disable
          recursion
  -r, --disable-recursion
          Disable discovered subdirectory scanning
      --scrape-listable
          Enable scraping of listable directories for urls, often produces large
          amounts of output
  -a, --user-agent <user_agent>
          Set the user-agent provided with requests, by default it isn't set
  -c, --cookie <cookie>
          Provide a cookie in the form "name=value", can be used multiple times
  -H, --header <header>
          Provide an arbitrary header in the form "header:value" - headers with
          no value must end in a semicolon
  -S, --silent
          Don't output information during the scan, only output the report at
          the end.
  -v, --verbose...
          Increase the verbosity level. Use twice for full verbosity.
  -B, --code-blacklist <code_blacklist>...
          Provide a comma separated list of response codes to not show in output
      --disable-validator
          Disable automatic detection of not found codes
  -W, --code-whitelist <code_whitelist>...
          Provide a comma separated list of response codes to show in output,
          also disables detection of not found codes
      --scan-401
          Scan folders even if they return 401 - Unauthorized frequently
      --scan-403
          Scan folders if they return 403 - Forbidden frequently
  -h, --help
          Print help
  -V, --version
          Print version

OUTPUT FORMAT:
    + [url] - File
    D [url] - Directory
    L [url] - Listable Directory

EXAMPLE USE:
    - Run against a website using the default dirble_wordlist.txt from the
      current directory:
        dirble [address]

    - Run with a different wordlist and including .php and .html extensions:
        dirble [address] -w example_wordlist.txt -x .php,.html

    - With listable directory scraping enabled:
        dirble [address] --scrape-listable

    - Providing a list of extensions and a list of URIs:
        dirble [address] -X wordlists/web.lst -U uri-list.txt

    - Providing multiple hosts to scan via command line:
        dirble [address] -u [address] -u [address]
"""

class Opt:
    def __init__(self):
        self.uris=[]; self.uri_files=[]; self.verb='get'; self.wordlist=None
        self.prefix_vals=[]; self.prefix_files=[]; self.ext_vals=[]; self.ext_files=[]
        self.ext_sub=False; self.force_extension=False; self.ignore_cert=False
        self.show_htaccess=False; self.timeout=5; self.max_errors=5
        self.json_file=None; self.output_file=None; self.xml_file=None; self.output_all=None
        self.hide_lengths=[]; self.max_threads=10; self.wordlist_split=3; self.throttle=0
        self.username=None; self.password=None; self.scan_listable=False; self.max_recursion_depth=None
        self.disable_recursion=False; self.scrape_listable=False; self.user_agent=None
        self.cookies=[]; self.headers=[]; self.silent=False; self.verbose=0
        self.code_blacklist=[]; self.disable_validator=False; self.code_whitelist=None
        self.no_color=False; self.proxy=None; self.no_proxy=False; self.burp=False

class Result:
    def __init__(self, url, code, size, body=b'', is_directory=False, is_listable=False, redirect_url='', found_from_listable=False):
        self.url=url; self.code=code; self.size=size; self.body=body or b''
        self.is_directory=is_directory; self.is_listable=is_listable; self.redirect_url=redirect_url
        self.found_from_listable=found_from_listable
    def line(self):
        sym = 'L' if self.is_listable else ('D' if self.is_directory else '+')
        s = f"{sym} {self.url} (CODE:{self.code}|SIZE:{self.size}"
        if self.redirect_url:
            s += f"|DEST:{self.redirect_url}"
        return s + ")"
    def json_obj(self):
        return {"url":self.url,"code":self.code,"size":self.size,"is_directory":self.is_directory,
                "is_listable":self.is_listable,"redirect_url":self.redirect_url,
                "found_from_listable":self.found_from_listable}

class Validator:
    def __init__(self, code=None, fixed_size=None, diff_size=None, bodies=None):
        self.code=code; self.fixed_size=fixed_size; self.diff_size=diff_size; self.bodies=bodies or []
        self.repeat_byte=None
        if self.bodies and all(b and len(set(b))==1 for b in self.bodies):
            bs={b[:1] for b in self.bodies}
            if len(bs)==1: self.repeat_byte=next(iter(bs))
    def hides(self, res):
        if self.code is None or res.code != self.code: return False
        if self.code == 404: return True
        if self.fixed_size is not None: return res.size == self.fixed_size
        if self.diff_size is not None:
            if res.body in self.bodies: return True
            if self.repeat_byte and res.body and len(set(res.body))==1 and res.body[:1]==self.repeat_byte: return True
        return False

def eprint(s): print(s, file=sys.stderr)
def out(opt, s):
    if not opt.silent: print(s)

def die_parse(msg, usage=False, tip=None):
    eprint(msg)
    if tip:
        eprint(''); eprint(f"  tip: {tip}")
    if usage:
        eprint(''); eprint('Usage: executable [OPTIONS] <uri|--uri-file <uri-file>|--uri <uri>>')
    eprint(''); eprint("For more information, try '--help'.")
    sys.exit(2)

def need_value(args, i, name):
    if i+1 >= len(args) or (args[i+1].startswith('-') and args[i+1] != '-'):
        die_parse(f"error: a value is required for '{name}' but none was supplied")
    return args[i+1]

def parse(argv):
    opt=Opt(); i=0; pos=[]
    while i < len(argv):
        a=argv[i]
        if a == '--help' or a == '-h': print(HELP, end=''); sys.exit(0)
        if a == '--version' or a == '-V': print(VERSION); sys.exit(0)
        if a == '--':
            pos += argv[i+1:]; break
        if a.startswith('--'):
            if '=' in a:
                name,val=a.split('=',1); have=True
            else:
                name=a; val=None; have=False
            def valreq():
                nonlocal i,val
                if have: return val
                v=need_value(argv,i,name); i+=1; return v
            if name in ('--uri','--url'): opt.uris.append(valreq())
            elif name in ('--uri-file','--url-file'): opt.uri_files.append(valreq())
            elif name == '--verb': opt.verb=valreq().lower()
            elif name == '--wordlist': opt.wordlist=valreq()
            elif name == '--prefixes': opt.prefix_vals.append(valreq())
            elif name == '--prefix-file': opt.prefix_files.append(valreq())
            elif name == '--extensions': opt.ext_vals.append(valreq())
            elif name == '--extension-file': opt.ext_files.append(valreq())
            elif name == '--ext-sub': opt.ext_sub=True
            elif name == '--force-extension': opt.force_extension=True
            elif name == '--ignore-cert': opt.ignore_cert=True
            elif name == '--show-htaccess': opt.show_htaccess=True
            elif name == '--timeout': opt.timeout=int(valreq())
            elif name == '--max-errors': opt.max_errors=int(valreq())
            elif name in ('--json-file','--oJ'): opt.json_file=valreq()
            elif name == '--no-color': opt.no_color=True
            elif name in ('--output-file','--oN'): opt.output_file=valreq()
            elif name in ('--xml-file','--oX'): opt.xml_file=valreq()
            elif name == '--hide-lengths': opt.hide_lengths.append(valreq())
            elif name in ('--output-all','--oA'): opt.output_all=valreq()
            elif name == '--burp': opt.burp=True; opt.proxy='http://localhost:8080'
            elif name == '--no-proxy': opt.no_proxy=True
            elif name == '--proxy': opt.proxy=valreq()
            elif name == '--max-threads': opt.max_threads=int(valreq())
            elif name == '--wordlist-split': opt.wordlist_split=int(valreq())
            elif name == '--throttle': opt.throttle=int(valreq())
            elif name == '--username': opt.username=valreq()
            elif name == '--password': opt.password=valreq()
            elif name == '--scan-listable': opt.scan_listable=True
            elif name == '--max-recursion-depth': opt.max_recursion_depth=int(valreq())
            elif name == '--disable-recursion': opt.disable_recursion=True
            elif name == '--scrape-listable': opt.scrape_listable=True
            elif name == '--user-agent': opt.user_agent=valreq()
            elif name == '--cookie': opt.cookies.append(valreq())
            elif name == '--header': opt.headers.append(valreq())
            elif name == '--silent': opt.silent=True
            elif name == '--verbose': opt.verbose += 1
            elif name == '--code-blacklist': opt.code_blacklist.append(valreq())
            elif name == '--disable-validator': opt.disable_validator=True
            elif name == '--code-whitelist':
                if opt.code_whitelist is None: opt.code_whitelist=[]
                opt.code_whitelist.append(valreq())
            elif name in ('--scan-401','--scan-403'):
                pass
            else:
                die_parse(f"error: unexpected argument '{a}' found", usage=True, tip=f"to pass '{a}' as a value, use '-- {a}'")
        elif a.startswith('-') and a != '-':
            # short options; -vv is a verbosity cluster, other options take values
            if set(a[1:]) == {'v'}:
                opt.verbose += len(a)-1
            elif a in ('-u',): opt.uris.append(need_value(argv,i,a)); i+=1
            elif a in ('-U',): opt.uri_files.append(need_value(argv,i,a)); i+=1
            elif a == '-w': opt.wordlist=need_value(argv,i,'--wordlist <wordlist>'); i+=1
            elif a == '-p': opt.prefix_vals.append(need_value(argv,i,a)); i+=1
            elif a == '-P': opt.prefix_files.append(need_value(argv,i,a)); i+=1
            elif a == '-x': opt.ext_vals.append(need_value(argv,i,a)); i+=1
            elif a == '-X': opt.ext_files.append(need_value(argv,i,a)); i+=1
            elif a == '-f': opt.force_extension=True
            elif a == '-k': opt.ignore_cert=True
            elif a == '-o': opt.output_file=need_value(argv,i,a); i+=1
            elif a == '-t': opt.max_threads=int(need_value(argv,i,a)); i+=1
            elif a == '-T': opt.wordlist_split=int(need_value(argv,i,a)); i+=1
            elif a == '-z': opt.throttle=int(need_value(argv,i,a)); i+=1
            elif a == '-l': opt.scan_listable=True
            elif a == '-r': opt.disable_recursion=True
            elif a == '-a': opt.user_agent=need_value(argv,i,a); i+=1
            elif a == '-c': opt.cookies.append(need_value(argv,i,a)); i+=1
            elif a == '-H': opt.headers.append(need_value(argv,i,a)); i+=1
            elif a == '-S': opt.silent=True
            elif a == '-B': opt.code_blacklist.append(need_value(argv,i,a)); i+=1
            elif a == '-W':
                if opt.code_whitelist is None: opt.code_whitelist=[]
                opt.code_whitelist.append(need_value(argv,i,a)); i+=1
            else:
                die_parse(f"error: unexpected argument '{a}' found", usage=True, tip=f"to pass '{a}' as a value, use '-- {a}'")
        else:
            pos.append(a)
        i += 1
    if opt.verb not in ('get','head','post'):
        die_parse(f"error: invalid value '{opt.verb}' for '--verb <http_verb>'")
    if pos:
        opt.uris = [pos[0]] + opt.uris
        for extra in pos[1:]: opt.uris.append(extra)
    return opt

def split_csv(vals):
    r=[]
    for v in vals:
        for p in v.split(','):
            r.append(p.strip())
    return r

def panic_file(path):
    eprint('')
    eprint(f"thread 'main' (0) panicked at src/wordlist.rs:112:37:")
    eprint('called `Result::unwrap()` on an `Err` value: Os { code: 2, kind: NotFound, message: "No such file or directory" }')
    eprint('note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace')
    sys.exit(101)

def read_lines(path, panic=True):
    try:
        with open(path, 'r', errors='replace') as f:
            return f.read().splitlines()
    except FileNotFoundError:
        if panic: panic_file(path)
        return None

def load_wordlist(opt):
    wl=opt.wordlist
    if not wl:
        exe=os.path.abspath(sys.argv[0])
        candidate=os.path.join(os.path.dirname(exe), 'dirble_wordlist.txt')
        if not os.path.exists(candidate):
            eprint('[ERROR] Unable to find default wordlist'); sys.exit(1)
        wl=candidate
    lines=read_lines(wl)
    words=[ln.strip().lstrip('/') for ln in lines]
    try:
        return sorted(words)
    except Exception:
        return words

def load_affixes(opt):
    prefixes=[]; exts=[]
    prefixes += split_csv(opt.prefix_vals)
    for pf in opt.prefix_files:
        prefixes += [x.strip() for x in read_lines(pf)]
    exts += split_csv(opt.ext_vals)
    for ef in opt.ext_files:
        exts += [x.strip() for x in read_lines(ef)]
    prefixes=[p for p in prefixes if p!='']
    exts=[e for e in exts if e!='']
    return [''] + sorted(prefixes), ([] if opt.force_extension else ['']) + sorted(exts)

def parse_codes(vals):
    s=set()
    for v in vals or []:
        for p in v.split(','):
            p=p.strip()
            if p:
                try: s.add(int(p))
                except ValueError: pass
    return s

def parse_ranges(vals):
    ranges=[]
    for v in vals or []:
        for p in v.split(','):
            p=p.strip()
            if not p: continue
            if '-' in p:
                a,b=p.split('-',1); ranges.append((int(a), int(b)))
            else:
                x=int(p); ranges.append((x,x))
    return ranges

def valid_uri(u):
    sp=urlsplit(u)
    return bool(sp.scheme) and bool(sp.netloc)

def normalize_target(u):
    sp=urlsplit(u)
    if not sp.path:
        return urlunsplit((sp.scheme, sp.netloc, '/', '', ''))
    return urlunsplit((sp.scheme, sp.netloc, sp.path, sp.query, ''))

def collect_targets(opt):
    targets=[]
    for u in opt.uris:
        if not valid_uri(u):
            die_parse(f"error: invalid value '{u}' for '[uri]': relative URL without a base")
        targets.append(normalize_target(u))
    for f in opt.uri_files:
        for line in read_lines(f):
            u=line.strip()
            if not valid_uri(u):
                if not opt.silent: print(f"Invalid URL: {u}")
            else:
                targets.append(normalize_target(u))
    if not targets:
        eprint(HELP, end=''); sys.exit(2)
    return targets

def build_headers(opt, url):
    h={'Accept':'*/*'}
    sp=urlsplit(url)
    user = opt.username; pw = opt.password
    if (user is None or pw is None) and sp.username is not None:
        user=unquote(sp.username); pw=unquote(sp.password or '')
    if user is not None and pw is not None:
        token=base64.b64encode((user+':'+pw).encode()).decode()
        h['Authorization']='Basic '+token
    if opt.user_agent: h['User-Agent']=opt.user_agent
    if opt.cookies: h['Cookie']='; '.join(opt.cookies)
    for hv in opt.headers:
        if ':' in hv:
            k,v=hv.split(':',1); h[k.strip()]=v.strip()
        elif hv.endswith(';'):
            h[hv[:-1].strip()]=''
    return h

def request_url(url, opt):
    sp=urlsplit(url)
    if sp.scheme not in ('http','https'):
        return None, f'Curl error after requesting {url} : [1] Unsupported protocol (Protocol "{sp.scheme}" not supported)'
    host=sp.hostname; port=sp.port
    path=urlunsplit(('', '', sp.path or '/', sp.query, ''))
    headers=build_headers(opt,url)
    method=opt.verb.upper()
    try:
        if sp.scheme=='https':
            ctx=ssl._create_unverified_context() if opt.ignore_cert else None
            conn=http.client.HTTPSConnection(host, port, timeout=opt.timeout, context=ctx)
        else:
            conn=http.client.HTTPConnection(host, port, timeout=opt.timeout)
        if method == 'POST':
            # match curl-ish empty chunked form post closely enough for servers that log it
            conn.putrequest('POST', path)
            conn.putheader('Host', sp.netloc.split('@')[-1])
            for k,v in headers.items(): conn.putheader(k, v)
            conn.putheader('Transfer-Encoding','chunked')
            conn.putheader('Content-Type','application/x-www-form-urlencoded')
            conn.putheader('Expect','100-continue')
            conn.endheaders()
            conn.send(b'0\r\n\r\n')
        else:
            conn.request(method, path, headers=headers)
        resp=conn.getresponse()
        body=b'' if method=='HEAD' else resp.read()
        loc=resp.getheader('Location') or ''
        final_url=urlunsplit((sp.scheme, sp.netloc, sp.path or '/', sp.query, ''))
        res=Result(final_url, resp.status, len(body), body, redirect_url='')
        res.location_header=loc
        conn.close()
        return res, None
    except socket.timeout:
        return None, f'Curl error after requesting {url} : [28] Timeout was reached (Operation timed out after {opt.timeout * 1000} milliseconds)'
    except ConnectionRefusedError:
        return None, f'Curl error after requesting {url} : [7] Could not connect to server (Failed to connect to {host} port {port or (443 if sp.scheme=="https" else 80)} after 0 ms: Could not connect to server)'
    except Exception as e:
        msg=str(e) or e.__class__.__name__
        code='7' if isinstance(e, OSError) else '52'
        return None, f'Curl error after requesting {url} : [{code}] {msg}'

def is_dir_redirect(url, loc):
    if not loc: return None
    dest=urljoin(url, loc)
    a=urlsplit(url); b=urlsplit(dest)
    orig=urlunsplit((a.scheme,a.netloc,(a.path or '/').rstrip('/')+'/', '', ''))
    got=urlunsplit((b.scheme,b.netloc,b.path, '', ''))
    return dest if got == orig else None

def is_listable_body(body):
    t=body.decode('utf-8','ignore').lower()
    return 'index of' in t and 'parent directory' in t

def fetch_candidate(url, opt):
    if opt.verbose >= 2:
        ts=time.strftime('%H:%M:%S')
        out(opt, f"{ts} [TRACE] (5) dirble::request: [src/request.rs:114] Requesting {url}")
    res,err=request_url(url,opt)
    if err: return None,err
    if res.code in (301,302,303,307,308):
        dest=is_dir_redirect(url, getattr(res,'location_header',''))
        if dest:
            r2,err2=request_url(dest,opt)
            if err2: return None,err2
            r2.url=dest
            r2.is_directory=True
            r2.is_listable=is_listable_body(r2.body)
            return r2,None
        else:
            res.redirect_url=urljoin(url, getattr(res,'location_header','')) if getattr(res,'location_header','') else ''
    return res,None

def random_path(n):
    return ''.join(random.choice(string.ascii_letters+string.digits) for _ in range(n))

def validate_base(base, opt):
    if opt.disable_validator or opt.code_whitelist is not None:
        return None, True
    vals=[]; errors=0
    for n in (10,20,30):
        u=urljoin(base, random_path(n))
        r,err=request_url(u,opt)
        if err:
            errors += 1; out(opt, err)
        else:
            vals.append(r)
    if errors >= 3:
        out(opt, f"[WARN] {base} errored too often during validation, skipping scanning")
        return None, False
    if not vals: return None, True
    codes={v.code for v in vals}; sizes=[v.size for v in vals]
    code=vals[0].code
    if len(codes)==1:
        if len(set(sizes))==1:
            if code==404:
                out(opt, f"[INFO] Detected nonexistent paths for {base} are (CODE:{code})")
                return Validator(code=code, bodies=[v.body for v in vals]), True
            else:
                out(opt, f"[INFO] Detected nonexistent paths for {base} are (CODE:{code}|SIZE:{sizes[0]})")
                return Validator(code=code, fixed_size=sizes[0], bodies=[v.body for v in vals]), True
        else:
            mid=sizes[1] if len(sizes)>1 else sizes[0]
            out(opt, f"[INFO] Detected nonexistent paths for {base} are (CODE:{code}|DIFF_SIZE:{mid})")
            return Validator(code=code, diff_size=mid, bodies=[v.body for v in vals]), True
    return None, True

def make_queries(words, prefixes, exts, opt):
    for pre in prefixes:
        for ext in exts:
            for w in words:
                if opt.ext_sub:
                    yield pre + w.replace('%EXT%', ext)
                else:
                    yield pre + w + ext

def should_show(res, opt, validator, black, white, ranges):
    if validator and validator.hides(res): return False
    if white is not None and res.code not in white: return False
    if res.code in black: return False
    if (not opt.show_htaccess) and res.code == 403 and '.ht' in urlsplit(res.url).path: return False
    for a,b in ranges:
        if a <= res.size <= b: return False
    return True

def join_candidate(base, q):
    # urljoin deliberately treats bases without trailing slash as files, as the original does.
    return urljoin(base, q)

def scan_target(target, opt, words, prefixes, exts, black, white, ranges):
    results=[]; per_target_base=target
    validator, ok = validate_base(target,opt)
    if not ok: return results
    if opt.wordlist_split < max(0,opt.max_threads-2) and opt.max_threads==10 and opt.wordlist_split==3:
        out(opt, f"[INFO] Increasing wordlist-split for initial scan of {target} to 8")
    maxdepth = opt.max_recursion_depth if opt.max_recursion_depth is not None else 25
    if opt.disable_recursion: maxdepth = 0
    seen=set(); queue=[(target,0)]
    while queue:
        base,depth=queue.pop(0)
        if base in seen: continue
        seen.add(base)
        if opt.verbose>=1:
            ts=time.strftime('%H:%M:%S'); out(opt, f"{ts} [DEBUG] (5) dirble::request_thread: Scanning {base}")
        consecutive_errors=0
        for q in make_queries(words,prefixes,exts,opt):
            u=join_candidate(base,q)
            if opt.throttle: time.sleep(opt.throttle/1000.0)
            res,err=fetch_candidate(u,opt)
            if err:
                consecutive_errors += 1; out(opt, err)
                if opt.max_errors and consecutive_errors >= opt.max_errors:
                    out(opt, f"[WARN] Thread scanning {u} stopping due to multiple consecutive errors received")
                    break
                continue
            consecutive_errors=0
            if should_show(res,opt,validator,black,white,ranges):
                out(opt,res.line()); results.append(res)
            if res.is_directory and depth < maxdepth:
                if (not res.is_listable) or opt.scan_listable:
                    if res.url not in seen:
                        queue.append((res.url, depth+1))
        if opt.verbose>=1:
            ts=time.strftime('%H:%M:%S'); out(opt, f"{ts} [DEBUG] (5) dirble::request_thread: Finished scanning {base}")
    return results

def write_reports(opt, grouped):
    # output-all only fills unset individual names, matching observed behavior.
    if opt.output_all and not (opt.output_file or opt.json_file or opt.xml_file):
        opt.output_file=opt.output_all+'.txt'; opt.json_file=opt.output_all+'.json'; opt.xml_file=opt.output_all+'.xml'
    allres=[]
    for _,rs in grouped: allres.extend(rs)
    if opt.output_file:
        with open(opt.output_file,'w') as f:
            for target,rs in grouped:
                f.write(f"Dirble Scan Report for {target}:\n")
                for r in rs: f.write(r.line()+"\n")
                f.write("\n")
    if opt.json_file:
        objs=[r.json_obj() for r in allres]
        with open(opt.json_file,'w') as f:
            if not objs: f.write('[]')
            else:
                parts=[json.dumps(o,separators=(',',':')) for o in objs]
                f.write('[' + ',\n'.join(parts) + ']')
    if opt.xml_file:
        with open(opt.xml_file,'w') as f:
            f.write('<?xml version="1.0" encoding="UTF-8"?>\n<dirble_scan>\n')
            for r in allres:
                f.write('<path url="{}" code="{}" content_len="{}" is_directory="{}" is_listable="{}" redirect_url="{}" found_from_listable="{}"/>\n'.format(
                    html.escape(r.url,quote=True), r.code, r.size, str(r.is_directory).lower(), str(r.is_listable).lower(), html.escape(r.redirect_url,quote=True), str(r.found_from_listable).lower()))
            f.write('</dirble_scan>')

def main():
    opt=parse(sys.argv[1:])
    targets=collect_targets(opt)
    words=load_wordlist(opt)
    prefixes,exts=load_affixes(opt)
    black=parse_codes(opt.code_blacklist)
    white=parse_codes(opt.code_whitelist) if opt.code_whitelist is not None else None
    ranges=parse_ranges(opt.hide_lengths)
    grouped=[]
    for t in targets:
        rs=scan_target(t,opt,words,prefixes,exts,black,white,ranges)
        grouped.append((t,rs))
    if opt.verbose>=1:
        ts=time.strftime('%H:%M:%S'); out(opt, f"{ts} [DEBUG] (3) dirble::output_thread: Received signal to end, generating the report")
    write_reports(opt,grouped)

if __name__=='__main__':
    try:
        main()
    except BrokenPipeError:
        pass
